            outputDir.set(layout.buildDirectory.dir("generated/assets/help/${variant.name}"))
        }
        variant.sources.assets?.addGeneratedSourceDirectory(
            helpAssetsTask,
            GenerateHelpAssetsTask::outputDir
        )
    }
}

